SCENE OD-B01-S01 "The Gods Consider Odysseus" {
  SOURCE Fagles book=1 pages=3..4;
  FRAME HALFWORLD.MONOCHROME_PAPER_V1;
  ACTIVE [location.olympian-council-hall, character.zeus, character.athena, ensemble.assembly-of-gods, divine-fx.poseidons-absence];
  SCRIPTS [TYPE.DIVINE_COUNCIL, TYPE.TEMPTATION, TYPE.RELEASE_FROM_CAPTIVITY];
  PROTOCOLS [PROTOCOL.NOSTOS, PROTOCOL.KLEOS, PROTOCOL.METIS, PROTOCOL.DIVINE_ORDER];
  BEAT 10 ASSEMBLE actor=[ensemble.assembly-of-gods] target=[world] {
    INTENT "The Olympian gods assemble while Poseidon is absent among the Ethiopians.";
    FORMULAS [FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="The Olympian gods assemble while Poseidon is absent among the Ethiopians.";
  }
  BEAT 20 REMEMBER actor=[character.zeus, ensemble.assembly-of-gods] target=[world] {
    INTENT "Zeus recalls Aegisthus and argues that mortals enlarge the suffering they blame on gods.";
    FORMULAS [FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Zeus recalls Aegisthus and argues that mortals enlarge the suffering they blame on gods.";
  }
  BEAT 30 ADVANCE_STATE actor=[character.athena] target=[world] {
    INTENT "Athena redirects the council toward Odysseus, captive on Calypso's island.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING, FORMULA_FAMILY.ATHENA_NAMING, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Athena redirects the council toward Odysseus, captive on Calypso's island.";
  }
  BEAT 40 DECLARE actor=[character.zeus] target=[world] {
    INTENT "Zeus names Poseidon's anger as the obstacle and permits a plan for Odysseus's return.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING, FORMULA_FAMILY.NOSTOS_LANGUAGE, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Zeus names Poseidon's anger as the obstacle and permits a plan for Odysseus's return.";
  }
  REQUIRE [causal_order, source_fidelity, entity_continuity, independent_instances, single_master_clock];
  COMMIT exit_state;
}

SCENE OD-B01-S02 "Athena's Two-Part Plan" {
  SOURCE Fagles book=1 pages=5..6;
  FRAME HALFWORLD.MONOCHROME_PAPER_V1;
  ACTIVE [character.athena, character.hermes, prop.golden-winged-sandals, prop.athenas-bronze-spear, divine-fx.olympus-to-ithaca-descent];
  SCRIPTS [TYPE.PLAN_AND_MISSION, TYPE.RELEASE_FROM_CAPTIVITY, TYPE.DIVINE_MESSAGE];
  PROTOCOLS [PROTOCOL.NOSTOS, PROTOCOL.METIS, PROTOCOL.DIVINE_ORDER, PROTOCOL.KINSHIP];
  BEAT 10 PLAN actor=[character.athena, character.hermes] target=[world] {
    INTENT "Athena proposes sending Hermes to Ogygia with the decree that Calypso release Odysseus.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING, FORMULA_FAMILY.ATHENA_NAMING, FORMULA_FAMILY.SPEECH_HANDOFF, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Athena proposes sending Hermes to Ogygia with the decree that Calypso release Odysseus.";
  }
  BEAT 20 PLAN actor=[character.athena] target=[world] {
    INTENT "She assigns herself the journey to Ithaca to awaken courage in Telemachus.";
    FORMULAS [FORMULA_FAMILY.NOSTOS_LANGUAGE];
    EFFECT commit="She assigns herself the journey to Ithaca to awaken courage in Telemachus.";
  }
  BEAT 30 RELEASE actor=[character.athena] target=[world] {
    INTENT "The gods accept the divided operation: release the father and activate the son.";
    FORMULAS [FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="The gods accept the divided operation: release the father and activate the son.";
  }
  BEAT 40 DEPART actor=[character.athena] target=[world] {
    INTENT "Athena fastens her golden sandals, takes her spear, and leaves Olympus.";
    FORMULAS [FORMULA_FAMILY.ATHENA_NAMING, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Athena fastens her golden sandals, takes her spear, and leaves Olympus.";
  }
  REQUIRE [causal_order, source_fidelity, entity_continuity, independent_instances, single_master_clock];
  COMMIT exit_state;
}

SCENE OD-B01-S03 "The Stranger at the Threshold" {
  SOURCE Fagles book=1 pages=6..7;
  FRAME HALFWORLD.MONOCHROME_PAPER_V1;
  ACTIVE [location.odysseuss-palace-threshold-and-hall, character.athena-as-mentes, character.telemachus, ensemble.the-suitors, ensemble.palace-servants];
  SCRIPTS [TYPE.XENIA_ARRIVAL, TYPE.SACRIFICE_FEAST, TYPE.PALACE_ENTRY];
  PROTOCOLS [PROTOCOL.XENIA, PROTOCOL.METIS, PROTOCOL.DIVINE_ORDER, PROTOCOL.HOUSEHOLD_SOVEREIGNTY, PROTOCOL.KINSHIP];
  BEAT 10 ARRIVE actor=[character.athena-as-mentes, ensemble.palace-servants] target=[world] {
    INTENT "Athena arrives at Odysseus's palace disguised as Mentes and waits at the outer gate.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING, FORMULA_FAMILY.ATHENA_NAMING, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Athena arrives at Odysseus's palace disguised as Mentes and waits at the outer gate.";
  }
  BEAT 20 PREPARE actor=[ensemble.the-suitors, ensemble.palace-servants] target=[world] {
    INTENT "The suitors gamble and feast while servants prepare wine, tables, and meat.";
    FORMULAS [FORMULA_FAMILY.FEAST_SATIATION];
    EFFECT commit="The suitors gamble and feast while servants prepare wine, tables, and meat.";
  }
  BEAT 30 OBSERVE actor=[character.telemachus] target=[world] {
    INTENT "Telemachus notices the unattended stranger and crosses the hall in shame.";
    FORMULAS [FORMULA_FAMILY.XENIA_LANGUAGE];
    EFFECT commit="Telemachus notices the unattended stranger and crosses the hall in shame.";
  }
  BEAT 40 WELCOME actor=[ensemble.the-suitors] target=[world] {
    INTENT "He greets her, takes her spear, and leads her away from the suitors' noise.";
    EFFECT commit="He greets her, takes her spear, and leads her away from the suitors' noise.";
  }
  REQUIRE [causal_order, source_fidelity, entity_continuity, independent_instances, single_master_clock];
  COMMIT exit_state;
}

SCENE OD-B01-S04 "Mentes Questions the Prince" {
  SOURCE Fagles book=1 pages=14..15;
  FRAME HALFWORLD.MONOCHROME_PAPER_V1;
  ACTIVE [character.athena-as-mentes, character.telemachus, prop.guest-chair-and-footstool, prop.golden-pitcher-and-silver-basin, sound-source.feast-noise];
  SCRIPTS [TYPE.PRIVATE_COUNSEL, TYPE.XENIA_ARRIVAL, TYPE.PALACE_ENTRY];
  PROTOCOLS [PROTOCOL.XENIA, PROTOCOL.DIVINE_ORDER, PROTOCOL.HOUSEHOLD_SOVEREIGNTY, PROTOCOL.RECOGNITION, PROTOCOL.KINSHIP, PROTOCOL.STORY_EXCHANGE];
  BEAT 10 WELCOME actor=[character.telemachus] target=[world] {
    INTENT "Telemachus seats the stranger in honor and sits close enough to speak privately.";
    FORMULAS [FORMULA_FAMILY.SEA_REGISTER, FORMULA_FAMILY.XENIA_LANGUAGE];
    EFFECT commit="Telemachus seats the stranger in honor and sits close enough to speak privately.";
  }
  BEAT 20 ADVANCE_STATE actor=[character.telemachus] target=[world] {
    INTENT "He complains that the suitors consume another man's wealth while Odysseus is presumed dead.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING];
    EFFECT commit="He complains that the suitors consume another man's wealth while Odysseus is presumed dead.";
  }
  BEAT 30 RECOGNIZE actor=[character.athena-as-mentes] target=[world] {
    INTENT "Athena, still as Mentes, gives a plausible identity and declares that Odysseus lives.";
    FORMULAS [FORMULA_FAMILY.ODYSSEUS_NAMING, FORMULA_FAMILY.ATHENA_NAMING, FORMULA_FAMILY.SPEECH_HANDOFF, FORMULA_FAMILY.DIVINE_AUTHORITY];
    EFFECT commit="Athena, still as Mentes, gives a plausible identity and declares that Odysseus lives.";
  }
  BEAT 40 RECOGNIZE actor=[character.telemachus] target=[world] {
    INTENT "She studies Telemachus's resemblance to his father and asks why the palace is overrun.";
    FORMULAS [FORMULA_FAMILY.SPEECH_HANDOFF];
    EFFECT commit="She studies Telemachus's resemblance to his father and asks why the palace is overrun.";
  }
  REQUIRE [causal_order, source_fidelity, entity_continuity, independent_instances, single_master_clock];
  COMMIT exit_state;
}

